-- CF Toronto Eaton Centre, rebuilt from its leasing plans (Phase 3: the shell).
--
-- The geometry comes from Data/*.lua, generated by tools/eaton/extract.py and
-- tools/eaton/to_lua.py from the real plans. Everything there is in plan feet:
--   u = feet north of the Queen St wall, v = feet west of the Yonge St wall.
-- Here 1 plan foot = 0.5 studs across the floor plan (agreed scale); heights use
-- full human scale (20 studs a level), so the galleria rises about 80 studs.
--
-- Built: floor plates with the real floor openings, exterior walls with the
-- street entrances, unit walls and storefront headers on their traced lines,
-- glass balustrades round the openings, the columns that stand in public space,
-- the glass barrel vault over the galleria, the roof, and working lifts.
-- Later phases: escalators and stairs, the concourse, storefronts, interiors.
local CollectionService = game:GetService("CollectionService")

local Util = require(script.Parent.Util)
local Kit = require(script.Parent.StationKit)
local Workplaces = require(script.Parent.Workplaces)

local DATA = script.Data
local LEVEL_DATA = {
	{ key = "L1", name = "Level_01", label = "Level 1", data = require(DATA.L1) },
	{ key = "L2", name = "Level_02", label = "Level 2", data = require(DATA.L2) },
	{ key = "L3", name = "Level_03", label = "Level 3", data = require(DATA.L3) },
}
local SHARED = require(DATA.Shared)

local EatonCentre = {}

local S = 0.5 -- studs per plan foot
local LEVEL_H = 20
local SLAB = 1
local HEADER = 13 -- storefront header starts this high above the floor

local V3 = Vector3.new
local M = Enum.Material
local C = Color3.fromRGB

local FLOOR = C(224, 220, 212)
local PLASTER = C(236, 234, 228)
local FASCIA = C(206, 206, 210) -- storefront bulkhead (sign bands come with the storefront phase)
local FACADE = C(168, 160, 150)
local FACADE_DARK = C(92, 96, 104)
local STEEL = C(196, 198, 202)
local GLASS = C(196, 222, 232)

local function folderIn(parent, name)
	local f = Instance.new("Folder")
	f.Name = name
	f.Parent = parent
	return f
end

-- Build. rect = T.EATON; the Yonge St wall is rect.maxX, the Queen St wall rect.maxZ.
function EatonCentre.build(root, rect)
	local yongeX, queenZ = rect.maxX, rect.maxZ
	local base = Util.WALK_TOP

	local function P(u, v, y)
		return V3(yongeX - v * S, y, queenZ - u * S)
	end

	local function levelY(i)
		return base + (i - 1) * LEVEL_H
	end
	local roofY = levelY(4)

	-- A flat rectangle in plan feet, top at y.
	local function plate(parent, r, y, thick, colour, material, collide)
		local u0, v0, u1, v1 = r[1], r[2], r[3], r[4]
		local size = V3((v1 - v0) * S, thick, (u1 - u0) * S)
		local cf = CFrame.new(P((u0 + u1) / 2, (v0 + v1) / 2, y - thick / 2))
		if collide == false then
			return Util.deco(parent, size, cf, colour, material)
		end
		return Util.solid(parent, size, cf, colour, material)
	end

	-- A vertical panel along a plan segment, from y up by height.
	local function panel(parent, a, b, y, height, thick, colour, material, collide)
		local pa, pb = P(a[1], a[2], 0), P(b[1], b[2], 0)
		local length = (pb - pa).Magnitude
		if length < 0.2 then
			return nil
		end
		local mid = (pa + pb) / 2 + V3(0, y + height / 2, 0)
		local cf = CFrame.lookAt(mid, mid + (pb - pa))
		local size = V3(thick, height, length + thick * 0.5)
		if collide == false then
			return Util.deco(parent, size, cf, colour, material)
		end
		return Util.solid(parent, size, cf, colour, material)
	end

	local mall = folderIn(root, "EatonCentre")
	local levels = {}

	---------------------------------------------------------------------------
	-- Floors, walls, storefront headers, balustrades.
	---------------------------------------------------------------------------
	for i, L in ipairs(LEVEL_DATA) do
		local y = levelY(i)
		local f = folderIn(mall, L.name)
		local arch = folderIn(f, "Architecture")
		local retail = folderIn(f, "Retail")
		local atrium = folderIn(f, "Atrium")
		levels[i] = { folder = f, y = y }

		for _, r in ipairs(L.data.slabs) do
			local p = plate(arch, r, y, SLAB, FLOOR, M.Marble)
			p.Name = "Floor"
		end

		local top = (i == 3) and (roofY - y) or (LEVEL_H - SLAB)
		for _, w in ipairs(L.data.walls) do
			local a, b, kind = { w[1], w[2] }, { w[3], w[4] }, w[5]
			if kind == 1 then
				panel(retail, a, b, y, top, 0.5, PLASTER, M.SmoothPlastic)
			elseif kind == 2 then
				-- Storefront: a fascia band for the sign; the shop front opens below.
				local h = panel(retail, a, b, y + HEADER, top - HEADER, 0.6, FASCIA, M.SmoothPlastic)
				if h then
					h.Name = "StorefrontHeader"
				end
			elseif kind == 3 then
				local wall = panel(arch, a, b, y, top + ((i == 3) and 3 or 0), 1.2, FACADE, M.Concrete)
				if wall then
					wall.Name = "ExteriorWall"
				end
			elseif kind == 4 then
				-- Street entrance: open below, glass transom and a dark lintel above.
				panel(arch, a, b, y + 12, 1.5, 1.4, FACADE_DARK, M.Metal)
				local t = panel(arch, a, b, y + 13.5, top - 13.5, 0.4, GLASS, M.Glass, false)
				if t then
					t.Transparency = 0.45
					t.Name = "EntranceGlass"
				end
			end
		end

		-- Glass balustrades with a steel handrail round every floor opening.
		for _, r in ipairs(L.data.rails) do
			local g = panel(atrium, { r[1], r[2] }, { r[3], r[4] }, y, 3.6, 0.25, GLASS, M.Glass)
			if g then
				g.Transparency = 0.55
				g.CastShadow = false
				g.Name = "Balustrade"
			end
			panel(atrium, { r[1], r[2] }, { r[3], r[4] }, y + 3.6, 0.3, 0.45, STEEL, M.Metal)
		end
	end

	---------------------------------------------------------------------------
	-- Columns (public spaces), floor to roof, with a soft light on each level.
	---------------------------------------------------------------------------
	local structure = folderIn(mall, "Structure")
	for k, c in ipairs(SHARED.columns) do
		local p = P(c[1], c[2], 0)
		local height = roofY - base
		Util.cylinder(structure, height, 1.8, CFrame.new(p.X, base + height / 2, p.Z), C(244, 244, 240), M.SmoothPlastic, true)
		if k % 2 == 0 then
			for i = 1, 3 do
				local holder = Util.deco(structure, V3(0.2, 0.2, 0.2), CFrame.new(p.X, levelY(i) + LEVEL_H - 3, p.Z), C(255, 255, 255), M.Neon)
				holder.Transparency = 1
				local light = Instance.new("PointLight")
				light.Range = 26
				light.Brightness = 0.9
				light.Color = C(255, 240, 220)
				light.Shadows = false
				light.Parent = holder
			end
		end
	end

	---------------------------------------------------------------------------
	-- Roof: solid over the shops, flat glass over openings, and the galleria's
	-- glass barrel vault along the skylight traced on the roof plan.
	---------------------------------------------------------------------------
	local roofFolder = folderIn(mall, "Roof")
	for _, r in ipairs(SHARED.roof) do
		plate(roofFolder, r, roofY + SLAB, SLAB, C(80, 84, 90), M.Concrete)
	end
	for _, r in ipairs(SHARED.skylights) do
		local g = plate(roofFolder, r, roofY + 0.4, 0.3, GLASS, M.Glass)
		g.Transparency = 0.5
		g.CastShadow = false
	end
	-- The vault: where the skylight runs straight, consecutive strips with the
	-- same span merge into barrel-vault bays (one constant rise, like the real
	-- galleria); where it runs diagonally (the Dundas end), flat framed glass.
	local strips = SHARED.vault
	local function centreOf(st)
		return (st[3] + st[4]) / 2
	end
	local bays, flats = {}, {}
	for k, st in ipairs(strips) do
		local prev, nxt = strips[k - 1], strips[k + 1]
		local shifting = (prev and math.abs(prev[2] - st[1]) < 0.5 and math.abs(centreOf(prev) - centreOf(st)) > 2)
			or (nxt and math.abs(st[2] - nxt[1]) < 0.5 and math.abs(centreOf(nxt) - centreOf(st)) > 2)
		if shifting then
			table.insert(flats, st)
		else
			local last = bays[#bays]
			if last and math.abs(last[2] - st[1]) < 0.5 and math.abs(last[3] - st[3]) <= 3 and math.abs(last[4] - st[4]) <= 3 then
				last[2] = st[2]
				last[3] = math.min(last[3], st[3])
				last[4] = math.max(last[4], st[4])
			else
				table.insert(bays, { st[1], st[2], st[3], st[4] })
			end
		end
	end
	local vault = folderIn(mall, "Galleria_Vault")
	local PANES = 10
	local RIB = C(246, 246, 244)
	for _, bay in ipairs(bays) do
		local u0, u1, v0, v1 = bay[1], bay[2], bay[3], bay[4]
		local span = (v1 - v0) * S
		local radius = span / 2
		local rise = math.min(radius * 0.75, 10)
		local length = (u1 - u0) * S
		local centre = P((u0 + u1) / 2, (v0 + v1) / 2, roofY)
		local function arc(a, z)
			return V3(centre.X + radius * math.cos(a), roofY + rise * math.sin(a), z or centre.Z)
		end
		for n = 0, PANES - 1 do
			local a0, a1 = n / PANES * math.pi, (n + 1) / PANES * math.pi
			local p0, p1 = arc(a0), arc(a1)
			local mid = (p0 + p1) / 2
			local chord = (p1 - p0).Magnitude + 0.2
			local tilt = math.atan2(p1.Y - p0.Y, p1.X - p0.X)
			local pane = Util.solid(vault, V3(chord, 0.25, length), CFrame.new(mid) * CFrame.Angles(0, 0, tilt), GLASS, M.Glass)
			pane.Transparency = 0.4
			pane.CastShadow = false
		end
		for _, z in ipairs({ centre.Z - length / 2, centre.Z + length / 2 }) do
			for n = 0, PANES - 1 do
				Util.beam(vault, arc(n / PANES * math.pi, z) + V3(0, 0.2, 0), arc((n + 1) / PANES * math.pi, z) + V3(0, 0.2, 0), 0.5, RIB, M.Metal)
			end
		end
		for _, side in ipairs({ -1, 1 }) do
			Util.solid(vault, V3(1, 1.2, length), CFrame.new(centre.X + side * radius, roofY + 0.6, centre.Z), RIB, M.Metal)
		end
	end
	for _, st in ipairs(flats) do
		local g = plate(vault, { st[1], st[3], st[2], st[4] }, roofY + 1.2, 0.3, GLASS, M.Glass)
		g.Transparency = 0.4
		g.CastShadow = false
		plate(vault, { st[1], st[3], st[1] + 0.8, st[4] }, roofY + 1.6, 0.8, RIB, M.Metal)
	end

	---------------------------------------------------------------------------
	-- Lifts: glass cabs at every level a shaft serves (from the plans' lift
	-- symbols, grouped across levels). Prompts move you between floors.
	---------------------------------------------------------------------------
	local vertical = folderIn(mall, "Vertical_Connections")
	local liftFolder = folderIn(vertical, "Elevators")
	local shafts = {}
	for i, L in ipairs(LEVEL_DATA) do
		for _, lift in ipairs(L.data.lifts) do
			local found
			for _, s in ipairs(shafts) do
				if math.abs(s.u - lift.u) < 6 and math.abs(s.v - lift.v) < 6 then
					found = s
				end
			end
			if not found then
				found = { u = lift.u, v = lift.v, w = lift.w, d = lift.d, stops = {} }
				table.insert(shafts, found)
			end
			found.stops[i] = true
		end
	end
	local liftCount = 0
	for _, s in ipairs(shafts) do
		local stops = {}
		for i = 1, 3 do
			if s.stops[i] then
				table.insert(stops, i)
			end
		end
		if #stops >= 2 then
			liftCount += 1
			local w = math.max(4, s.w * S)
			local d = math.max(4, s.d * S)
			local cabs = {}
			for _, i in ipairs(stops) do
				local y = levelY(i)
				local p = P(s.u, s.v, y)
				local cab = {}
				-- Floor plate, glass sides, steel roof; open on all sides at floor level.
				Util.solid(liftFolder, V3(w, 0.3, d), CFrame.new(p + V3(0, 0.15, 0)), C(70, 72, 78), M.Metal)
				local roof = Util.solid(liftFolder, V3(w, 0.4, d), CFrame.new(p + V3(0, 9, 0)), STEEL, M.Metal)
				Kit.light(roof, Enum.NormalId.Bottom, 12, 1, C(255, 246, 230))
				for _, sx in ipairs({ -1, 1 }) do
					local g = Util.solid(liftFolder, V3(0.2, 8.6, d), CFrame.new(p + V3(sx * w / 2, 4.6, 0)), GLASS, M.Glass)
					g.Transparency = 0.5
				end
				local panelPart = Util.solid(liftFolder, V3(0.6, 3, 1), CFrame.new(p + V3(-w / 2 + 0.6, 3.5, -d / 2 + 0.6)), C(40, 42, 48), M.Metal)
				cab.centre = CFrame.new(p + V3(0, 3, 0))
				cab.panel = panelPart
				cab.level = i
				cabs[i] = cab
			end
			for _, i in ipairs(stops) do
				local cab = cabs[i]
				for n, j in ipairs(stops) do
					if j ~= i then
						local target = cabs[j]
						local prompt = Instance.new("ProximityPrompt")
						prompt.ActionText = "Go to " .. LEVEL_DATA[j].label
						prompt.ObjectText = "Elevator"
						prompt.KeyboardKeyCode = n == 1 and Enum.KeyCode.E or (n == 2 and Enum.KeyCode.R or Enum.KeyCode.T)
						prompt.HoldDuration = 0.2
						prompt.MaxActivationDistance = 8
						prompt.RequiresLineOfSight = false
						prompt.UIOffset = Vector2.new(0, (n - 1) * 60)
						prompt.Parent = cab.panel
						prompt.Triggered:Connect(function(player)
							local character = player.Character
							local rootPart = character and character:FindFirstChild("HumanoidRootPart")
							if rootPart and (rootPart.Position - cab.centre.Position).Magnitude < 14 then
								character:PivotTo(target.centre * cab.centre:ToObjectSpace(rootPart.CFrame))
							end
						end)
					end
				end
			end
		end
	end

	---------------------------------------------------------------------------
	-- Signs over the main street entrances.
	---------------------------------------------------------------------------
	local signage = folderIn(mall, "Signage")
	local entrances = {}
	for _, w in ipairs(LEVEL_DATA[1].data.walls) do
		if w[5] == 4 then
			local len = math.sqrt((w[3] - w[1]) ^ 2 + (w[4] - w[2]) ^ 2)
			table.insert(entrances, { w = w, len = len })
		end
	end
	table.sort(entrances, function(a, b)
		return a.len > b.len
	end)
	for k = 1, math.min(6, #entrances) do
		local w = entrances[k].w
		local pa, pb = P(w[1], w[2], 0), P(w[3], w[4], 0)
		local mid = (pa + pb) / 2
		local along = (pb - pa).Unit
		local out = V3(along.Z, 0, -along.X)
		-- Face the street: the side away from the mall centre.
		local centre = P(700, 160, 0)
		if (mid - centre):Dot(out) < 0 then
			out = -out
		end
		local signCF = CFrame.lookAt(mid + out * 1.2 + V3(0, base + 16.5, 0), mid + out * 5 + V3(0, base + 16.5, 0))
		local board = Util.deco(signage, V3(math.min(26, entrances[k].len * S), 3, 0.4), signCF, C(24, 24, 28), M.SmoothPlastic)
		Util.sign(board, Enum.NormalId.Front, "EATON CENTRE", C(255, 255, 255), Enum.Font.GothamBlack).LightInfluence = 0
	end

	---------------------------------------------------------------------------
	-- Workplaces move into real units: Grind Coffee (a café counter) and
	-- Metro Threads (a clothing store) on Level 1.
	---------------------------------------------------------------------------
	local units = LEVEL_DATA[1].data.units
	local function frontInfo(u)
		local f = u.front
		if not f then
			return nil
		end
		local len = math.sqrt((f[3] - f[1]) ^ 2 + (f[4] - f[2]) ^ 2)
		return f, len
	end
	local workFolder = folderIn(levels[1].folder, "Interactive_Objects")
	local placed = {}
	-- Metro Threads: a front along the corridor (constant v), at least 60 ft wide
	-- and 60 ft deep, so the 30 x 30-stud store fits.
	local best
	for _, u in ipairs(units) do
		local f, len = frontInfo(u)
		if f and not u.inferred and math.abs(f[6]) > 0.9 and len >= 60 and (u.vmax - u.vmin) >= 62 then
			if not best or (u.area or 0) > (best.area or 0) then
				best = u
			end
		end
	end
	if best then
		local f = best.front
		local vf = (f[2] + f[4]) / 2
		local um = (f[1] + f[3]) / 2
		-- Outside is toward +v (normal +v) or -v; the store runs the other way.
		local inward = f[6] > 0 and 1 or -1 -- outside at larger v = smaller x, so go +x
		local xFront = yongeX - vf * S
		local zc = queenZ - um * S
		local ok, err = pcall(Workplaces.clothing, workFolder, base, xFront, inward, zc - 15, zc + 15, "THREADS_EATON", "threads")
		if not ok then
			warn("[EatonCentre] Metro Threads failed: " .. tostring(err))
		else
			placed.threads = best.unit
		end
	end
	-- Grind Coffee: a unit at least 34 ft across its front and 24 ft deep.
	local cafe
	for _, u in ipairs(units) do
		local f, len = frontInfo(u)
		if f and not u.inferred and u.unit ~= placed.threads and len >= 34 and math.min(u.umax - u.umin, u.vmax - u.vmin) >= 24 and (u.area or 0) > 0 and u.area < 4000 then
			local coffee = (u.name or ""):upper():find("COFFEE") ~= nil
			if not cafe or (coffee and not cafe.coffee) or (coffee == cafe.coffee and (u.area or 0) < (cafe.u.area or 0)) then
				cafe = { u = u, coffee = coffee }
			end
		end
	end
	if cafe then
		local f = cafe.u.front
		local mu, mv = (f[1] + f[3]) / 2, (f[2] + f[4]) / 2
		local front = P(mu, mv, base)
		local outward = P(mu + f[5], mv + f[6], base) - front
		outward = V3(outward.X, 0, outward.Z).Unit
		local back = front - outward * 11.5
		local ok, err = pcall(Workplaces.cafe, workFolder, CFrame.lookAt(back, back + outward), 16, "GRIND_EATON", "grind")
		if not ok then
			warn("[EatonCentre] Grind Coffee failed: " .. tostring(err))
		else
			placed.grind = cafe.u.unit
		end
	end
	print(string.format("[EatonCentre] built from plans: %d lifts, %d vault bays, Metro Threads in %s, Grind Coffee in %s",
		liftCount, #bays, tostring(placed.threads), tostring(placed.grind)))

	CollectionService:AddTag(mall, "EatonCentre")
	return mall
end

return EatonCentre
